  var regular=matchRules.TrainingDeck("WARRIOR");var raw=new RawDeckCode{Format=3,Hero=catalog.Pool(regular.PoolId).HeroDbfIds["WARRIOR"],Cards=matchRules.TrainingDeck("MAGE").Cards.ToDictionary(pair=>catalog.Card(pair.Key).DbfId,pair=>pair.Value)};Reject(()=>DeckCode.Decode(catalog,DeckCode.EncodeRaw(raw),regular.PoolId),"Warrior hero with Mage card IDs rejected at import");
