  match=g;matchViewSeat=0;awaitHandoff=false;ClearPending();BeginCard(fire=g.Players[0].Hand.First(h=>h.CardId=="VAN_CS2_029").Id);Check(pending==""&&status.Text.Contains("本职业"),"UI refuses cross-class card selection");
  var test=new MatchEngine(catalog,regular,matchRules.TrainingDeck("MAGE"),42,true);test.MarkMulliganCompleteForTests();test.Players[0].Deck.Add("VAN_CS2_029");count=test.Players[0].Deck.Count;Check(!test.TestTakeCard(0,"VAN_CS2_029").Success&&test.Players[0].Deck.Count==count,"Test take cannot bypass profession restriction");
  var savedDraft=draft;var saved=new SavedDeck{Id="class-binding-fixture",Name="职业绑定测试",PoolId=regular.PoolId,Code=DeckCode.Encode(catalog,regular)};savedDecks.Add(saved);try{draft=matchRules.TrainingDeck("MAGE");RefreshLanDecks();lanDeck.SelectedItem=((Choice[])lanDeck.ItemsSource).First(c=>c.Key==saved.Id);Check(((Choice)lanClass.SelectedItem).Key=="WARRIOR"&&!lanClass.IsEnabled,"Saved deck binds and locks LAN profession");Check(LobbyDeck(lanClass,lanDeck).ClassId=="WARRIOR","LAN starts using saved deck profession");lanDeck.SelectedItem=((Choice[])lanDeck.ItemsSource).First(c=>c.Key=="draft");Check(((Choice)lanClass.SelectedItem).Key=="MAGE"&&!lanClass.IsEnabled,"Draft binds and locks profession");RefreshLobbyDecks();myDeck.SelectedItem=((Choice[])myDeck.ItemsSource).First(c=>c.Key==saved.Id);opponentDeck.SelectedItem=((Choice[])opponentDeck.ItemsSource).First(c=>c.Key=="draft");Check(((Choice)myClass.SelectedItem).Key=="WARRIOR"&&!myClass.IsEnabled&&((Choice)opponentClass.SelectedItem).Key=="MAGE"&&!opponentClass.IsEnabled,"Both test players bind independent deck professions");myDeck.SelectedIndex=0;Check(myClass.IsEnabled,"Practice deck allows profession selection");lanDeck.SelectedIndex=0;Check(lanClass.IsEnabled,"Practice LAN deck allows profession selection");ShowPage("lobby");ApplyMode(true);Render(Path.Combine(folder,"64-deck-class-binding.png"));}finally{draft=savedDraft;savedDecks.Remove(saved);RefreshLobbyDecks();RefreshLanDecks();}
  JsonData.Write(Path.Combine(folder,"class-restriction-verification.json"),new{Assertions=checks-before,DeckClassBound=true,CrossClassPlayBlocked=true,ImportExportValidated=true,HostValidation=true,TestRestriction=true});
